import { defineAsyncComponent, markRaw, type Component } from 'vue'
// The widget registry of `@frigear-nu/widget` (a hard dependency): items are widgets of the area `dashboard.<name>`.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { widgets as registry } from '#widgets/registry'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { dashboards } from '#dashboard/registry'
import { dashboardArea } from '../../shared/registry'

const cache = new Map<string, Component>()

/** The lazily loaded component of a dashboard item. */
export function getDashboardComponent(name: string, id: string): Component | undefined {
  const area = dashboardArea(name)
  const key = `${area}::${id}`
  if (!cache.has(key)) {
    const widget = (registry[area] ?? []).find((item: { id: string }) => item.id === id)
    if (!widget) return undefined
    cache.set(key, markRaw(defineAsyncComponent(widget.component)))
  }
  return cache.get(key)
}

/**
 * Every item id of a dashboard in this build, in registered order: the items of every platform and permission, so a
 * layout change never drops or reorders items the current viewer does not see.
 */
export function getDashboardItemIds(name: string): string[] {
  const entries = (dashboards as Record<string, Record<string, unknown>>)[name] ?? {}
  return (registry[dashboardArea(name)] ?? [])
    .map((item: { id: string }) => item.id)
    .filter((id: string) => id in entries)
}
